package snippets.java.spring;

import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import reactor.core.publisher.*;
import java.time.Duration;
import java.util.Map;

/**
 * Spring WebFlux — Non-blocking Reactive REST Controller
 * Replaces Spring MVC when you need high concurrency with fewer threads.
 */
@RestController
@RequestMapping("/api/users")
public class WebFluxController {

    private final UserReactiveService userService;

    WebFluxController(UserReactiveService userService) { this.userService = userService; }

    // Returns Mono<T> — single async result
    @GetMapping("/{id}")
    public Mono<ResponseEntity<User>> getUser(@PathVariable Long id) {
        return userService.findById(id)
            .map(user -> ResponseEntity.ok(user))
            .defaultIfEmpty(ResponseEntity.notFound().build());
    }

    // Returns Flux<T> — streaming multiple results
    @GetMapping(produces = "application/json")
    public Flux<User> getAllUsers(
            @RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "20") int size) {
        return userService.findAll()
            .skip((long) page * size)
            .take(size)
            .delayElements(Duration.ofMillis(1)); // back-pressure demo
    }

    // Server-Sent Events (SSE) — real-time streaming to browser
    @GetMapping(value = "/stream", produces = "text/event-stream")
    public Flux<Map<String,Object>> liveStream() {
        return Flux.interval(Duration.ofSeconds(1))
            .map(tick -> Map.of("tick", tick, "ts", System.currentTimeMillis()));
    }

    @PostMapping
    public Mono<ResponseEntity<User>> createUser(@RequestBody Mono<CreateUserRequest> request) {
        return request
            .flatMap(userService::create)
            .map(u -> ResponseEntity.status(201).body(u));
    }

    @DeleteMapping("/{id}")
    public Mono<ResponseEntity<Void>> deleteUser(@PathVariable Long id) {
        return userService.delete(id)
            .then(Mono.just(ResponseEntity.<Void>noContent().build()));
    }

    // Combine multiple service calls (parallel execution)
    @GetMapping("/{id}/dashboard")
    public Mono<Map<String,Object>> dashboard(@PathVariable Long id) {
        Mono<User> user = userService.findById(id);
        Mono<Integer> orderCount = userService.getOrderCount(id);
        Mono<String> status = userService.getStatus(id);
        return Mono.zip(user, orderCount, status)
            .map(t -> Map.of("user", t.getT1(), "orders", t.getT2(), "status", t.getT3()));
    }

    // Placeholder types
    record User(Long id, String name) {}
    record CreateUserRequest(String name, String email) {}
    interface UserReactiveService {
        Mono<User> findById(Long id);
        Flux<User> findAll();
        Mono<User> create(CreateUserRequest req);
        Mono<Void> delete(Long id);
        Mono<Integer> getOrderCount(Long id);
        Mono<String> getStatus(Long id);
    }
}

package snippets.java.cache;

import redis.clients.jedis.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import java.util.function.*;

/**
 * Redis Cache Wrapper in Java (Jedis)
 * Cache-aside pattern with TTL and JSON serialization.
 */
public class RedisCache {

    private final JedisPool pool;
    private final ObjectMapper mapper;
    private static final int DEFAULT_TTL = 300; // 5 min

    public RedisCache(String redisUrl) {
        pool = new JedisPool(redisUrl);
        mapper = new ObjectMapper();
    }

    // Cache-aside: get from cache or compute and store
    public <T> T getOrSet(String key, Supplier<T> fetchFn, Class<T> type, int ttl) {
        try (Jedis jedis = pool.getResource()) {
            String cached = jedis.get(key);
            if (cached != null) return mapper.readValue(cached, type);
            T data = fetchFn.get();
            jedis.setex(key, ttl, mapper.writeValueAsString(data));
            return data;
        } catch (Exception e) {
            throw new RuntimeException("Cache error", e);
        }
    }

    public <T> T getOrSet(String key, Supplier<T> fetchFn, Class<T> type) {
        return getOrSet(key, fetchFn, type, DEFAULT_TTL);
    }

    public void invalidate(String key) {
        try (Jedis jedis = pool.getResource()) { jedis.del(key); }
    }

    public void invalidateByPattern(String pattern) {
        try (Jedis jedis = pool.getResource()) {
            Set<String> keys = jedis.keys(pattern);
            if (!keys.isEmpty()) jedis.del(keys.toArray(new String[0]));
        }
    }

    // Distributed lock (Redlock simplified)
    public boolean acquireLock(String lockKey, String token, int ttlSeconds) {
        try (Jedis jedis = pool.getResource()) {
            String result = jedis.set(lockKey, token, SetParams.setParams().nx().ex(ttlSeconds));
            return "OK".equals(result);
        }
    }

    public void releaseLock(String lockKey, String token) {
        try (Jedis jedis = pool.getResource()) {
            // Only release if we own the lock
            String luaScript = "if redis.call('get', KEYS[1]) == ARGV[1] then return redis.call('del', KEYS[1]) else return 0 end";
            jedis.eval(luaScript, List.of(lockKey), List.of(token));
        }
    }

    // Rate limiting (sliding window)
    public boolean isRateLimited(String userId, int maxRequests, int windowSeconds) {
        String key = "rl:" + userId;
        long now = System.currentTimeMillis();
        long windowStart = now - windowSeconds * 1000L;
        try (Jedis jedis = pool.getResource()) {
            jedis.zremrangeByScore(key, 0, windowStart); // remove old entries
            long count = jedis.zcard(key);
            if (count >= maxRequests) return true;
            jedis.zadd(key, now, UUID.randomUUID().toString());
            jedis.expire(key, windowSeconds);
            return false;
        }
    }

    public void close() { pool.close(); }

    // Usage example (illustrative)
    public static void main(String[] args) {
        RedisCache cache = new RedisCache("redis://localhost:6379");
        String user = cache.getOrSet("user:1:profile", () -> "{name:'Alice'}", String.class, 600);
        System.out.println(user);
        System.out.println("Rate limited: " + cache.isRateLimited("user1", 100, 60));
        cache.close();
    }
}

package snippets.java.patterns;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Predicate;

/**
 * Generic Repository Pattern in Java
 * Abstracts data access, enables easy swapping of implementations.
 */
public class RepositoryPattern {

    interface Entity { Long getId(); }

    // Generic Repository interface
    interface Repository<T extends Entity> {
        Optional<T> findById(Long id);
        List<T> findAll();
        List<T> findWhere(Predicate<T> filter);
        T save(T entity);
        boolean deleteById(Long id);
        long count();
    }

    // In-memory implementation (for testing / prototyping)
    abstract static class InMemoryRepository<T extends Entity> implements Repository<T> {
        protected final ConcurrentHashMap<Long, T> store = new ConcurrentHashMap<>();
        protected final AtomicLong idGen = new AtomicLong(1);

        public Optional<T> findById(Long id) { return Optional.ofNullable(store.get(id)); }
        public List<T> findAll() { return new ArrayList<>(store.values()); }
        public List<T> findWhere(Predicate<T> filter) { return store.values().stream().filter(filter).toList(); }
        public boolean deleteById(Long id) { return store.remove(id) != null; }
        public long count() { return store.size(); }
        protected abstract T assignId(T entity, Long newId);

        public T save(T entity) {
            if (entity.getId() == null) {
                T withId = assignId(entity, idGen.getAndIncrement());
                store.put(withId.getId(), withId);
                return withId;
            }
            store.put(entity.getId(), entity);
            return entity;
        }
    }

    // Domain entity
    record User(Long id, String name, String email, String role) implements Entity {
        public Long getId() { return id; }
    }

    // Concrete repository
    static class UserRepository extends InMemoryRepository<User> {
        public Optional<User> findByEmail(String email) {
            return store.values().stream().filter(u -> u.email().equalsIgnoreCase(email)).findFirst();
        }
        public List<User> findByRole(String role) {
            return findWhere(u -> u.role().equals(role));
        }
        protected User assignId(User u, Long id) { return new User(id, u.name(), u.email(), u.role()); }
    }

    // Service layer depends on interface (not implementation)
    static class UserService {
        private final Repository<User> repo;
        UserService(Repository<User> repo) { this.repo = repo; }

        public User register(String name, String email) {
            User u = new User(null, name, email, "user");
            return repo.save(u);
        }

        public Optional<User> getUser(Long id) { return repo.findById(id); }

        public List<User> getAdmins() { return repo.findWhere(u -> "admin".equals(u.role())); }
    }

    public static void main(String[] args) {
        UserRepository repo = new UserRepository();
        UserService service = new UserService(repo);

        User alice = service.register("Alice", "alice@example.com");
        User bob   = service.register("Bob",   "bob@example.com");
        repo.save(new User(null, "Charlie", "charlie@example.com", "admin"));

        System.out.println(service.getUser(alice.getId()));  // Optional[User[id=1,...]]  
        System.out.println(repo.findByEmail("bob@example.com").map(User::name));  // Optional[Bob]
        System.out.println(service.getAdmins()); // [User[id=3, name=Charlie, role=admin]]
        System.out.println("Total users: " + repo.count()); // 3
    }
}

# Microservices Design Patterns — Java/Spring Focus

## 1. API Gateway Pattern
```
 Client → API Gateway → [Auth Service]
                      → [User Service]
                      → [Order Service]
                      → [Product Service]

Spring Cloud Gateway example:
  @Bean
  RouteLocator routes(RouteLocatorBuilder b) {
    return b.routes()
      .route("user-service", r -> r.path("/api/users/**")
        .filters(f -> f.stripPrefix(1)
                        .circuitBreaker(c -> c.setName("user-cb")))
        .uri("lb://USER-SERVICE"))
      .build();
  }
```

## 2. Circuit Breaker (Resilience4j)
```java
@CircuitBreaker(name = "orderService", fallbackMethod = "fallbackOrders")
public List<Order> getOrders(Long userId) {
    return orderClient.getOrdersForUser(userId); // may fail
}

public List<Order> fallbackOrders(Long userId, Exception ex) {
    log.warn("Orders unavailable for user {}: {}", userId, ex.getMessage());
    return Collections.emptyList(); // graceful degradation
}

// States: CLOSED → normal, OPEN → fast-fail, HALF_OPEN → testing recovery
// application.yml:
// resilience4j.circuitbreaker.instances.orderService:
//   failure-rate-threshold: 50
//   wait-duration-in-open-state: 10s
```

## 3. Saga Pattern (Distributed Transactions)
```
ORCHESTRATION (via Spring State Machine or Temporal):
  SagaOrchestrator → PaymentService → InventoryService → ShippingService
  On failure → compensating transactions (undo each step)

CHOREOGRAPHY (Kafka events):
  OrderCreated event → PaymentService listens → PaymentDone event
                     → InventoryService listens → InventoryReserved event
```

## 4. Event Sourcing + CQRS
```java
// Command side — writes events to event store
@Aggregate
public class Order {
    @CommandHandler
    public Order(CreateOrderCommand cmd) {
        apply(new OrderCreatedEvent(cmd.orderId(), cmd.items()));
    }
    @EventSourcingHandler
    public void on(OrderCreatedEvent e) { this.id = e.orderId(); }
}
// Axon Framework handles event sourcing/CQRS boilerplate
```

## 5. Service Mesh (Istio / Linkerd)
```
Sidecar proxy (Envoy) injected alongside each pod:
  - mTLS between services
  - Traffic shaping, retries, timeouts
  - Distributed tracing (Jaeger)
  - Metrics (Prometheus)

Developers write no networking code —
the mesh handles it transparently.
```

## 6. When to Use Microservices
```
✅ Large teams (Conway's Law)
✅ Independent deployment/scaling needed
✅ Polyglot requirements

❌ Small team < 10 engineers
❌ Early startup — start with a monolith
❌ If bounded contexts unclear

Rule of thumb:
  Start monolith → define clear domain boundaries
  → extract service when team/scaling pain is *real*
```

package snippets.java.spring;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.header.writers.*;

/**
 * Spring Security — HTTP Security Headers Configuration
 */
@Configuration
public class SecurityHeaders {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            // Content-Security-Policy — prevent XSS
            .headers(headers -> headers
                .contentSecurityPolicy(csp -> csp
                    .policyDirectives(
                        "default-src 'self'; " +
                        "script-src 'self' https://cdn.jsdelivr.net; " +
                        "style-src 'self' 'unsafe-inline'; " +
                        "img-src 'self' data: https:; " +
                        "frame-ancestors 'none'"
                    )
                )
                // Strict-Transport-Security — force HTTPS
                .httpStrictTransportSecurity(hsts -> hsts
                    .maxAgeInSeconds(31_536_000)
                    .includeSubDomains(true)
                    .preload(true)
                )
                // Prevent MIME sniffing
                .contentTypeOptions(content -> {})
                // Prevent clickjacking
                .frameOptions(frame -> frame.deny())
                // Referrer policy
                .referrerPolicy(referrer -> referrer
                    .policy(org.springframework.security.web.header.writers.ReferrerPolicyHeaderWriter.ReferrerPolicy.STRICT_ORIGIN_WHEN_CROSS_ORIGIN)
                )
                // Permissions Policy
                .permissionsPolicy(permissions -> permissions
                    .policy("camera=(), microphone=(), geolocation=()")
                )
            )
            // CSRF — enabled by default, disable only for stateless APIs
            .csrf(csrf -> csrf.disable()) // disable for REST APIs using JWT
            // CORS configuration
            .cors(cors -> cors.configurationSource(request -> {
                var config = new org.springframework.web.cors.CorsConfiguration();
                config.setAllowedOrigins(java.util.List.of("https://yourfrontend.com"));
                config.setAllowedMethods(java.util.List.of("GET","POST","PUT","DELETE","OPTIONS"));
                config.setAllowedHeaders(java.util.List.of("Authorization","Content-Type"));
                config.setAllowCredentials(true);
                config.setMaxAge(3600L);
                return config;
            }))
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/actuator/health").permitAll()
                .requestMatchers("/api/public/**").permitAll()
                .anyRequest().authenticated()
            );
        return http.build();
        // Resulting headers:
        // Content-Security-Policy: default-src 'self'; ...
        // Strict-Transport-Security: max-age=31536000; includeSubDomains; preload
        // X-Content-Type-Options: nosniff
        // X-Frame-Options: DENY
        // Referrer-Policy: strict-origin-when-cross-origin
    }
}
